import{_ as r,o as s,c as i,aO as e}from"./chunks/framework.BFrk9dwu.js";const o="/recipes/braised-pork.jpg",a="/recipes/braised-pork/top-2.jpg",l="/recipes/braised-pork/top-3.jpg",p="/recipes/braised-pork/top-4.jpg",d="/recipes/braised-pork/step-1-a.jpg",g="/recipes/braised-pork/step-1-b.jpg",c="/recipes/braised-pork/step-2-a.jpg",n="/recipes/braised-pork/step-2-b.jpg",m="/recipes/braised-pork/step-3-a.jpg",_="/recipes/braised-pork/step-3-b.jpg",b="/recipes/braised-pork/step-4-a.jpg",h="/recipes/braised-pork/step-4-b.jpg",u="/recipes/braised-pork/step-5-a.jpg",f="/recipes/braised-pork/step-5-b.jpg",k="/recipes/braised-pork/step-6-a.jpg",y="/recipes/braised-pork/step-6-b.jpg",j="/recipes/braised-pork/step-7-a.jpg",z="/recipes/braised-pork/step-7-b.jpg",x="/recipes/braised-pork/step-8-a.jpg",P="/recipes/braised-pork/step-8-b.jpg",B=JSON.parse('{"title":"红烧肉","description":"煸油、炒糖色、小火慢炖再收汁的红烧肉做法，含发苦、油厚、肉柴的排查","frontmatter":{"date":"2026-11-15T15:52:16.000Z","title":"红烧肉","description":"煸油、炒糖色、小火慢炖再收汁的红烧肉做法，含发苦、油厚、肉柴的排查","permalink":"/pages/9959ef","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/braised-pork.md","filePath":"life/recipes/braised-pork.md"}'),q={name:"life/recipes/braised-pork.md"};function v(T,t,S,$,A,N){return s(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="红烧肉" tabindex="-1">红烧肉 <a class="header-anchor" href="#红烧肉" aria-label="Permalink to &quot;红烧肉&quot;">​</a></h1><p><strong>分类：家常小炒</strong></p><div class="recipe-gallery"><img src="'+o+'" alt="红烧肉成品：白瓷碗里枣红油亮的方块，撒了白芝麻与葱花"><img src="'+a+'" alt="俯拍特写：红烧肉肥瘦分层、酱汁挂在表面"><img src="'+l+'" alt="筷子夹起一块红烧肉，酱汁往下滴，旁边一碗白米饭"><img src="'+p+'" alt="原料摆拍：生五花肉方块、冰糖、姜片八角桂皮干辣椒"></div><p>红烧肉看着难，其实就四件事：肉挑对、油煸掉、糖色别炒过、火要小。糖色和收汁这两步最看手上功夫，颜色对了才算成。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>带皮五花肉</td><td>600g，挑三层肥瘦分明的，切 3cm 方块</td></tr><tr><td>生姜</td><td>5 片，2 片焯水、3 片炖</td></tr><tr><td>小葱</td><td>1 根切葱花，出锅撒</td></tr></tbody></table><p><strong>配料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>冰糖</td><td>25g，炒糖色用，没有就用等量白糖</td></tr><tr><td>食用油</td><td>15ml，炒糖色用，别多，肉本身会出油</td></tr><tr><td>八角</td><td>2 个，别多，多了发苦</td></tr><tr><td>桂皮</td><td>1 小段（约 3cm）</td></tr><tr><td>干辣椒</td><td>2 个，不吃辣可省</td></tr><tr><td>料酒</td><td>20ml，焯水 10ml、炒制 10ml</td></tr><tr><td>生抽</td><td>30ml，给咸鲜</td></tr><tr><td>老抽</td><td>8ml，给颜色，多了发黑</td></tr><tr><td>热水</td><td>800ml，必须热水</td></tr><tr><td>盐</td><td>2g，最后调</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>切块。</strong> 五花肉洗净擦干，切 3cm 见方的块。<strong>块别切小</strong>，炖完会缩一圈，2cm 的块炖出来只剩一点点。</p><figure class="recipe-shots"><img loading="lazy" src="'+d+'" alt="案板上整块带皮五花肉，旁边菜刀与切下的方块"><img loading="lazy" src="'+g+'" alt="切好的五花肉方块码在白盘里"></figure></li><li><p><strong>冷水焯水。</strong> 肉块冷水下锅，加 2 片姜、10ml 料酒，水开后撇净浮沫，煮 3 分钟捞出，用温水冲净、控干水分。</p><ul><li>控干很关键，带水下锅会溅油，也煸不出油。</li></ul><figure class="recipe-shots"><img loading="lazy" src="'+c+'" alt="五花肉块冷水下锅，水面浮起灰白浮沫"><img loading="lazy" src="'+n+'" alt="焯好后控在沥水篮里，用厨房纸吸干"></figure></li><li><p><strong>煸出油。</strong> 锅不放油，肉块皮朝下摊平，中小火煸 5 分钟，把肥肉里的油逼出来，煸到肉皮泛黄、边缘起小泡。煸出的猪油盛出大半，锅里留一层润锅就够。</p><ul><li>这步决定成菜会不会腻。油不煸出去，最后就是一碗油泡肉。</li></ul><figure class="recipe-shots"><img loading="lazy" src="'+m+'" alt="肉块皮朝下在锅里煸，锅底已经出了一层猪油"><img loading="lazy" src="'+_+'" alt="煸出的猪油盛在小碗里，锅里只留肉块"></figure></li><li><p><strong>炒糖色。</strong> 转最小火，下 15ml 油和 25g 冰糖，慢慢炒到化开、变成枣红色起细密小泡，立刻把肉块倒进去翻匀。<strong>看颜色别看时间</strong>，枣红一到就下肉，多炒十秒就是苦的。</p><figure class="recipe-shots"><img loading="lazy" src="'+b+'" alt="冰糖在油里化成枣红色、起小泡，旁边备着肉块"><img loading="lazy" src="'+h+'" alt="肉块翻匀糖色后通体枣红油亮"></figure></li><li><p><strong>下香料和酱油。</strong> 加 3 片姜、2 个八角、1 小段桂皮、2 个干辣椒炒香，沿锅边淋 10ml 料酒，再加 30ml 生抽、8ml 老抽翻匀上色。</p><figure class="recipe-shots"><img loading="lazy" src="'+u+'" alt="姜片、八角、桂皮、干辣椒下锅炒香"><img loading="lazy" src="'+f+'" alt="加了酱油后肉块颜色变深、酱汁挂上"></figure></li><li><p><strong>热水慢炖。</strong> 倒 800ml 热水没过肉块，大火烧开转最小火，盖盖炖 60 分钟。中途别加冷水，要加也加热水。</p><figure class="recipe-shots"><img loading="lazy" src="'+k+'" alt="热水没过肉块，汤色深红、浮着姜片八角"><img loading="lazy" src="'+y+'" alt="盖盖小火慢炖，锅边冒细汽"></figure></li><li><p><strong>开盖转大火。</strong> 60 分钟后开盖，肉皮发亮、筷子能轻松插透就转大火收汁，让汤汁翻滚收浓。</p><figure class="recipe-shots"><img loading="lazy" src="'+j+'" alt="开盖后肉已炖到软糯，汤剩一半"><img loading="lazy" src="'+z+'" alt="转大火，汤汁翻滚冒大泡、变浓稠"></figure></li><li><p><strong>收汁出锅。</strong> 收到酱汁能挂住勺背、裹在每块肉上就关火，撒葱花和白芝麻。<strong>别收到发干</strong>，凉了还会更稠。</p><figure class="recipe-shots"><img loading="lazy" src="'+x+'" alt="酱汁挂在勺背成一层厚膜"><img loading="lazy" src="'+P+'" alt="装碗后撒白芝麻与葱花"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>挑三层分明的五花</strong>：肥瘦层次清楚才不腻，软五花、下五花都行，别用纯肥的。</li><li><strong>先煸油，再炒糖色</strong>：油煸出去肉才不腻，也不容易崩油。</li><li><strong>糖色看颜色不看时间</strong>：枣红起小泡就下肉，再等就发苦。</li><li><strong>全程热水、小火炖</strong>：冷水一激肉就紧，火大了汤汁浑浊、肉散。</li><li><strong>收汁到挂勺就停</strong>：锅里看着稀一点正常，凉了会变稠。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>不会炒糖色就跳过第 4 步，直接用 15ml 老抽上色，颜色浅一点但不会翻车。或者用高压锅压 20 分钟，再倒回锅里收汁。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>发苦</strong>：糖色炒过头了，或者八角放多了。</li><li><strong>发黑不发红</strong>：老抽倒多了，糖色又没炒到位。</li><li><strong>太油腻</strong>：第 3 步没煸油，或者油没盛出去。</li><li><strong>肉柴不糯</strong>：中途加了冷水，或者炖的时间不够。</li><li><strong>汁发涩、不亮</strong>：收汁时火太大，汁收干烧焦了。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',16)])])}const C=r(q,[["render",v]]);export{B as __pageData,C as default};
